node.script:
function OnUpdate(so_self, time_key, length)
{
	 local t = 1 + 0.5 * cos(2* PI * time_key/length);
	 t *= 0.1;
	 Actor_SetModelGlowColor(so_self, t,t,t,1);
}

function OnStart(so_self, length)
{
}

function OnUpdate(so_self, time_key, length)
{
	 local offset = 1.15;
	 local t = 1 + 0.5 * cos(7* PI * time_key/length);

	 Actor_SetModelGlowColor(so_self, t,t,t,1);
}

function OnStart(so_self, length)
{
	Actor_SetModelGlowColor(so_self, 1,1,1,0.0);
}

function OnUpdate(so_self, time_key, length)
{
	 /*local kvs = StageObject_GetKeyValueStore(so_self)
	 local value = StageObject_GetKeyValue(so_self, "glow_value", 0);

	 if (value <= 1)
	 {

		 value = value + (0.3 * time_key);
		 Actor_SetModelGlowColor(so_self, value,value,value,1.0);
	 }*/

	 local offset = 1.15;
	 local t = m_clamp01f((time_key-offset) / (length-offset));

	 Actor_SetModelGlowColor(so_self, t,t,t,1);
}

node.interaction_1_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	local stage = StageObject_GetKeyValue(so_self, "stage", null);
	if (stage == null ||
		!string_contains_string(stage, "pet-stages/") ||
		string_contains_string(stage, "pet-stages/pet-hub.stage"))
	{
		Game_SetStagePointOfInterestCompleted(so_self);
	}
	else
	{
		if (Game_IsTombCompleted(stage))
			Game_SetStagePointOfInterestCompleted(so_self);
	}

	local pos = StageObject_GetPosition(so_self);

	local player_index = Game_GetPlayerIndexByActor(so_activator);
	StageObject_SetPosition(so_activator, pos[0] + 60 * player_index, pos[1], pos[2]);
	StageObject_SetAngle(so_activator, 40 * player_index);
	Actor_SetActorFlag(so_activator, "ONLY_VISIBLE_IN_EDITOR", true);
	Actor_PlayAnimationWithDelayPlaybackSpeedAndPosition(so_activator, "teleport_in", 0, 1, 0);
	Actor_PlayAnimationWithDelayPlaybackSpeedAndPosition(so_self, "stage_enter", 0, 1, 0);
}

node.interaction_3_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	local pos = StageObject_GetPosition(so_self);
	local so_plane = Stage_QueryNearestActorWithType(pos[0],pos[1],pos[2], 120, "actors/interactives/buried-teleporter-plane.xml");
//    local so_plane = StageObject_GetKeyValue(so_self, "plane");
	if (so_plane == null)
		return;
	Stage_KillActorAndStartDeathAnimation(so_plane);

	Actor_SetActorFlag(so_self, "ONLY_VISIBLE_IN_EDITOR", false);
	Actor_PlayAnimation(so_self, "idle");
//    Stage_DeleteStageObject(so_plane);
}

node.interaction_4_script_to_test_if_interact:
function IsInteractionAvailable(so_self, so_activator)
{
	if(Stage_GetFilename().find("pet-hub") != null)
		return false;
	if(StageObject_GetKeyValue(so_self, "unlocked", false))
		return false;
	if(Game_IsBuriedTeleporterFound(StageObject_GetId(so_self)))
		return false;
	if(Game_GetWorldState("BURIED_TELEPORTERS", StageObject_GetId(so_self)) == "-1")
		return false;

	local so_id = StageObject_GetId (so_self);
	if(Game_IsBuriedTeleporterDiggable(so_id) == false)
		return false;


	return true;
}

node.interaction_4_script_to_run_when_actor_e:
function OnActorEntersRadius(so_self, so_activator)
{
	local so_ref = StageObject_GetKeyValueStageObjectReference (so_activator, "ref_pet")

	if(Game_IsBuriedTeleporterFound(StageObject_GetId(so_self)))
		return;

	if(so_ref == null)
		return;

	if(!StageObject_HasTag (so_ref, "PET"))
		return;

	if(Game_GetWorldState ("BURIED_TELEPORTERS", StageObject_GetId(so_self)) == "-1")
		return;

	local current_action = Game_GetCurrentAction(so_ref);
	if (current_action == "InvestigateAction" || current_action == "AttackAction")
	{
		return;
	}
	//Game_StartInvestigate (so_ref, "Lure", so_self);
	local pos = StageObject_GetPosition (so_self);
	//Game_PlayAnimationByAction (so_ref, "discovery")
	//Game_StartMoveTo(so_ref, pos[0], pos[1]);
	//Game_PlayAnimationByAction (so_ref, "digging")

	StageObject_SetKeyValueBoolean (so_ref,"is_running",true);
	Actor_PlayAnimation (so_ref, "discovery");
	Game_StartInvestigate(so_ref, "NONE", so_self);


/*
	local pos = StageObject_GetPosition(so_self);
	local so_plane = Stage_QueryNearestActorWithType(pos[0],pos[1],pos[2], 120, "actors/interactives/buried-teleporter-plane.xml");
	if (so_plane != null)
	{
		Actor_PlayAnimationWithDelayPlaybackSpeedAndPosition(so_plane, "found",2,1,0);
	}
*/

	//Actor_QueueActionMoveToDistanceFromActor (so_ref,so_self, 30);
	//Actor_QueueActionPlayAnimation (so_ref,"digging",true);
}

node.interaction_5_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	local pos = StageObject_GetPosition(so_self);
	local so_plane = Stage_QueryNearestActorWithType(pos[0],pos[1],pos[2], 120, "actors/interactives/buried-teleporter-plane.xml");
	if (so_plane != null)
	{
		Actor_PlayAnimationWithDelayPlaybackSpeedAndPosition(so_plane, "found",0,1,0);
	} //so_self
	Game_SetWorldState("BURIED_TELEPORTERS", StageObject_GetId(so_self),"-1");
}
